use v5.42;
use strict;
use warnings;
use JSON::PP 'decode_json';
use Digest::SHA 'sha256_hex';
use lib 'bench/lib';
use Wump::BenchMatrix qw(load_capture compare);
my $dir=shift // 'bench';
sub contents ($path) {open my $in,'<',$path or die "$path: $!"; binmode $in; local $/; my $text=<$in>; close $in or die $!; return $text}
my $before=load_capture('bench/operation-matrix-select-current.json');
my $after=load_capture("$dir/operation-matrix-xs-current.json");
my $anchor=load_capture('bench/operation-matrix-callee-baseline.json');
my $fixture=sha256_hex(join '', map {contents($_)} qw(bench/matrix.pl bench/matrix-worker.pl bench/matrix-worker.go bench/lib/Wump/BenchMatrix.pm));
for my $spec ([$before,640],[$after,650]) {
 my ($capture,$successful)=@$spec;
 my @samples=map {@{$_->{samples}}} @{$capture->{cells}};
 @samples==770 && grep($_->{status} eq 'ok',@samples)==$successful && !$capture->{source}{dirty}
  && $capture->{source}{fixture_sha256} eq $fixture or die 'invalid matrix provenance/completion';
}
for my $control (qw(stock go)) {$before->{binaries}{$control}{sha256} eq $after->{binaries}{$control}{sha256} or die 'control changed'}
for my $spec ([$before,'check'],[$anchor,'anchor-check']) {
 my ($failed,$text)=compare($spec->[0],$after,10);
 $text eq contents("$dir/operation-matrix-xs-$spec->[1].txt") or die 'incorrect saved comparison';
 my $failures=()=$text=~/^FAIL /mg;
 print "ok - $spec->[1] saved exactly; gate status $failed ($failures failed metrics)\n";
}
my $m=decode_json(contents("$dir/xs-json-machine.json"));
$m->{source_revision} eq $after->{source}{revision} && $m->{before_source_revision} eq $before->{source}{revision} or die 'wrong harness sources';
for my $path (keys %{$m->{sha256}}) {
 my $text;
 if ($path =~ m{^/}) {$text=contents($path)}
 else {open my $in,'-|','git','show',"$m->{source_revision}:$path" or die $!; $text=do {local $/; <$in>}; close $in or die 'source unavailable'}
 sha256_hex($text) eq $m->{sha256}{$path} or die "changed source/binary/archive: $path";
}
for my $path (keys %{$m->{validation_log_sha256}}) {sha256_hex(contents($path)) eq $m->{validation_log_sha256}{$path} or die "changed validation log: $path"}
for my $role (keys %{$m->{runtime_archive_members}}) {
 for my $name (keys %{$m->{runtime_archive_members}{$role}}) {
  my $root='/home/marcus/projects/wump/master/build/checkpoint-xs-json';
  open my $in,'-|','ar','p',"$root/$role/perl/perl-5.42.2/libperl.a","$name.o" or die $!;
  my $bytes=do {local $/; <$in>}; close $in or die 'archive extraction failed';
  sha256_hex($bytes) eq $m->{runtime_archive_members}{$role}{$name} or die 'stale runtime archive';
 }
}
$m->{binaries}{before}{sha256} eq $before->{binaries}{wump}{sha256} && $m->{binaries}{current}{sha256} eq $after->{binaries}{wump}{sha256} or die 'wrong paired binaries';
print "ok - all 1540 samples, source/binary/archive/log hashes and exact gate reports verified\n";
